import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { createServiceClient } from "@/lib/supabase/service";
import { getCopyAccess } from "@/lib/copy-access";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const COPIER_BASE64 = "";

export async function GET(request: Request) {
  const auth = await createClient();
  const { data: { user } } = await auth.auth.getUser();
  if (!user) {
    return NextResponse.json({ error: "UNAUTHENTICATED" }, { status: 401 });
  }

  const url = new URL(request.url);
  const mt5Login = String(url.searchParams.get("mt5Login") || "").trim();
  if (!/^\\d{4,12}$/.test(mt5Login)) {
    return NextResponse.json({ error: "MT5_ID_REQUIRED", message: "Register and select your MT5 account before downloading the Copier." }, { status: 400 });
  }

  const db = createServiceClient();
  const { data: registration, error } = await db
    .from("copy_customer_registrations")
    .select("id")
    .eq("auth_user_id", user.id)
    .eq("mt5_login", mt5Login)
    .maybeSingle();

  if (error) return NextResponse.json({ error: "MT5_REGISTRATION_LOOKUP_FAILED" }, { status: 500 });
  if (!registration) {
    return NextResponse.json({ error: "MT5_NOT_REGISTERED", message: "Register this MT5 account before downloading the Copier." }, { status: 403 });
  }

  const access = await getCopyAccess(user.id, mt5Login);
  if (!access.active) {
    return NextResponse.json({ error: "COPY_SUBSCRIPTION_REQUIRED", message: "An active Copy Trading subscription or admin-granted access is required." }, { status: access.reason === "expired" ? 402 : 403 });
  }

  const file = Buffer.from(COPIER_BASE64, "base64");
  return new Response(file, {
    status: 200,
    headers: {
      "Content-Type": "application/octet-stream",
      "Content-Disposition": 'attachment; filename="VaultTrades_Copier.ex5"',
      "Content-Length": String(file.byteLength),
      "Cache-Control": "private, no-store, max-age=0",
      "X-Content-Type-Options": "nosniff",
    },
  });
}
